SELECT sysoo.*, (select nick_name from sys_user where user_id =sysoo.create_user) as createUserName FROM sto_yt_store_order_operation as sysoo WHERE is_deleted = 0
AND store_order_id =#{storeOrderId}
AND store_order_id IN (
#{item}
)
AND store_order_id IN ( SELECT id FROM sto_yt_store_order WHERE code LIKE CONCAT('%', #{orderCode}, '%') AND is_deleted = 0 )
AND store_order_id IN ( SELECT id FROM sto_yt_store_order WHERE type = #{orderType} AND is_deleted = 0 )
AND store_order_id IN ( SELECT id FROM sto_yt_store_order WHERE specification_id = #{specificationId} AND is_deleted = 0 )
AND store_order_id IN ( SELECT id FROM sto_yt_store_order WHERE customer_id = #{customerId} AND is_deleted = 0 )
AND create_time >= #{startTime}
AND #{endTime} >= create_time
ORDER BY create_time DESC
